# Let's look at all the transformations systematically
inputs = ['cyaw', 'eaaig', 'xh', 'bbd', 'kjaw']
outputs = ['cyxw', 'cxxig', 'xh', 'bbd', 'kfxew']

# Let's see if we can find patterns by looking at what changes
print("Detailed analysis:")
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    if inp != outp:
        print(f"\n{i}: '{inp}' -> '{outp}'")
        # Find positions where they differ
        diff_positions = []
        for j, (char_in, char_out) in enumerate(zip(inp, outp)):
            if char_in != char_out:
                diff_positions.append((j, char_in, char_out))
        print(f"  Differences at positions: {diff_positions}")

        # Check if we can identify substring replacements
        if len(outp) >= 2 and len(inp) >= 2:
            # Check if there are 2-character patterns
            for j in range(len(inp) - 1):
                if j < len(outp) - 1:
                    sub_in = inp[j:j+2]
                    sub_out = outp[j:j+2]
                    if sub_in != sub_out:
                        print(f"  Substring {j}:{j+2} changed from '{sub_in}' to '{sub_out}'")

